// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *JobQueue) InsertAll(records []*JobQueue, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.No,
			r.Description,
			r.Description_2,
			r.Status,
			r.Object_id_to_run,
			r.Parameter,
			r.Next_start,
			r.Minutes_between_run,
			r.Recurring_job,
			r.Recurrence,
			r.Notification_email,
			r.Notify_on,
			r.Notification_language,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, JobQueueTableName)
	columns := []string{"no", "description", "description_2", "status", "object_id_to_run", "parameter", "next_start", "minutes_between_run", "recurring_job", "recurrence", "notification_email", "notify_on", "notification_language"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *JobQueue) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, JobQueueTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			setClauses = append(setClauses, "no = ?")
			values = append(values, t.No)
		}
		if t.hasFieldChanged("description") {
			setClauses = append(setClauses, "description = ?")
			values = append(values, t.Description)
		}
		if t.hasFieldChanged("description_2") {
			setClauses = append(setClauses, "description_2 = ?")
			values = append(values, t.Description_2)
		}
		if t.hasFieldChanged("status") {
			setClauses = append(setClauses, "status = ?")
			values = append(values, t.Status)
		}
		if t.hasFieldChanged("object_id_to_run") {
			setClauses = append(setClauses, "object_id_to_run = ?")
			values = append(values, t.Object_id_to_run)
		}
		if t.hasFieldChanged("parameter") {
			setClauses = append(setClauses, "parameter = ?")
			values = append(values, t.Parameter)
		}
		if t.hasFieldChanged("next_start") {
			setClauses = append(setClauses, "next_start = ?")
			values = append(values, t.Next_start)
		}
		if t.hasFieldChanged("minutes_between_run") {
			setClauses = append(setClauses, "minutes_between_run = ?")
			values = append(values, t.Minutes_between_run)
		}
		if t.hasFieldChanged("recurring_job") {
			setClauses = append(setClauses, "recurring_job = ?")
			values = append(values, t.Recurring_job)
		}
		if t.hasFieldChanged("recurrence") {
			setClauses = append(setClauses, "recurrence = ?")
			values = append(values, t.Recurrence)
		}
		if t.hasFieldChanged("notification_email") {
			setClauses = append(setClauses, "notification_email = ?")
			values = append(values, t.Notification_email)
		}
		if t.hasFieldChanged("notify_on") {
			setClauses = append(setClauses, "notify_on = ?")
			values = append(values, t.Notify_on)
		}
		if t.hasFieldChanged("notification_language") {
			setClauses = append(setClauses, "notification_language = ?")
			values = append(values, t.Notification_language)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "description = ?")
		values = append(values, t.Description)
		setClauses = append(setClauses, "description_2 = ?")
		values = append(values, t.Description_2)
		setClauses = append(setClauses, "status = ?")
		values = append(values, t.Status)
		setClauses = append(setClauses, "object_id_to_run = ?")
		values = append(values, t.Object_id_to_run)
		setClauses = append(setClauses, "parameter = ?")
		values = append(values, t.Parameter)
		setClauses = append(setClauses, "next_start = ?")
		values = append(values, t.Next_start)
		setClauses = append(setClauses, "minutes_between_run = ?")
		values = append(values, t.Minutes_between_run)
		setClauses = append(setClauses, "recurring_job = ?")
		values = append(values, t.Recurring_job)
		setClauses = append(setClauses, "recurrence = ?")
		values = append(values, t.Recurrence)
		setClauses = append(setClauses, "notification_email = ?")
		values = append(values, t.Notification_email)
		setClauses = append(setClauses, "notify_on = ?")
		values = append(values, t.Notify_on)
		setClauses = append(setClauses, "notification_language = ?")
		values = append(values, t.Notification_language)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.No)
	}
	// Renamed key fields that other tables refer to (Rename): carried over below
	type renamedKey struct {
		field    string
		old, new interface{}
	}
	var renamed []renamedKey
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			renamed = append(renamed, renamedKey{"no", t.oldValues["no"], t.No})
		}
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND no = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Job_Queue: %v\n", err)
		return false
	}
	// A temporary record's rename stays in the record: other tables are not changed
	for _, r := range renamed {
		if t.temp != nil {
			break
		}
		if err := t.renameReferences(r.field, r.old, r.new); err != nil {
			fmt.Printf("Error: Failed to rename references to Job_Queue: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *JobQueue) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.No.Equal(old)
		}
	case "description":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Description.Equal(old)
		}
	case "description_2":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Description_2.Equal(old)
		}
	case "status":
		if old, ok := oldValue.(JobQueueStatus); ok {
			return t.Status != old
		}
	case "object_id_to_run":
		if old, ok := oldValue.(int); ok {
			return t.Object_id_to_run != old
		}
		return true // Type mismatch, assume changed
	case "parameter":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Parameter.Equal(old)
		}
	case "next_start":
		if old, ok := oldValue.(types.DateTime); ok {
			return !t.Next_start.Equal(old)
		}
	case "minutes_between_run":
		if old, ok := oldValue.(int); ok {
			return t.Minutes_between_run != old
		}
		return true // Type mismatch, assume changed
	case "recurring_job":
		if old, ok := oldValue.(bool); ok {
			return t.Recurring_job != old
		}
		return true // Type mismatch, assume changed
	case "recurrence":
		if old, ok := oldValue.(JobQueueRecurrence); ok {
			return t.Recurrence != old
		}
	case "notification_email":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Notification_email.Equal(old)
		}
	case "notify_on":
		if old, ok := oldValue.(JobQueueNotify_on); ok {
			return t.Notify_on != old
		}
	case "notification_language":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Notification_language.Equal(old)
		}
	}

	return false
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *JobQueue) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *JobQueue) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table  string
		global bool
		column string
	}
	references := map[string][]reference{
		"no": {{"Job_Queue_Entry", false, "job_queue_no"}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			query := t.convertPlaceholders(fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column), 2)
			if _, err := t.db.Exec(query, newValue, oldValue); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

